head.script:
scwin.init = function() {
    var jsonData = [{
            "col1": "a100",
            "col2": "b200",
            "col3": "c300",
            "col4": "d400",
            "col5": "e500"
        },
        {
            "col1": "a100",
            "col2": "b200",
            "col3": "c300",
            "col4": "d400",
            "col5": "e500"
        },
        {
            "col1": "a100",
            "col2": "b200",
            "col3": "c300",
            "col4": "d400",
            "col5": "e500"
        },
        {
            "col1": "a100",
            "col2": "b200",
            "col3": "c300",
            "col4": "d400",
            "col5": "e500"
        }
    ];
    dataList2.setJSON(jsonData);
    gridView2.setRowBackgroundColor(2, "blue");
};
scwin.trigger1_onclick = function(e) {
    var options = {};
    options.fileName = "test.xlsx";
    options.type = "1";
    options.startRowIndex = 7; //실제 데이터 위치
    options.startColumnIndex = 0;
    options.removeColumns = ""; //"1,3"
    options.bodyFontName = "궁서체";
    options.bodyFontSize = "30";
    options.headerFontName = "궁서체";
    options.headerFontSize = "30";
    options.useStyle = true;
    var infoArr = [];
    var infoObj = {
        rowIndex: 1,
        colIndex: 3,
        rowSpan: 1,
        colSpan: 2,
        text: "데이터 표시",
        textAlign: "center"
    };
    infoArr.push(infoObj);
    gridView2.advancedExcelDownload(options, infoArr);
};
scwin.onpageload = function() {
    scwin.init();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
